-- 成果治理审计与重复成果合并映射。
-- 治理状态只保留当前快照；本迁移增加不可变历史和显式合并映射，绝不删除来源成果。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研成果治理历史" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "成果类型" integer NOT NULL,
    "成果编号" integer NOT NULL,
    "原状态" varchar(10),
    "新状态" varchar(10) NOT NULL,
    "原规范成果类型" integer,
    "原规范成果编号" integer,
    "新规范成果类型" integer,
    "新规范成果编号" integer,
    "治理原因" varchar(1000),
    "变更动作" varchar(20) NOT NULL DEFAULT '更新',
    "操作人编号" integer NOT NULL,
    "操作时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果治理历史" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果治理历史_类型" CHECK ("成果类型" BETWEEN 1 AND 4),
    CONSTRAINT "ck_科研成果治理历史_状态" CHECK ("新状态" IN ('有效','待更正','已更正','已撤稿','重复')),
    CONSTRAINT "ck_科研成果治理历史_动作" CHECK ("变更动作" IN ('历史导入','新增','更新'))
);
CREATE INDEX IF NOT EXISTS "ix_科研成果治理历史_成果时间"
    ON "科研成果治理历史" ("成果类型", "成果编号", "操作时间" DESC, "编号" DESC);

CREATE TABLE IF NOT EXISTS "科研成果合并审计" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "来源成果类型" integer NOT NULL,
    "来源成果编号" integer NOT NULL,
    "规范成果类型" integer NOT NULL,
    "规范成果编号" integer NOT NULL,
    "合并原因" varchar(1000) NOT NULL,
    "操作人编号" integer NOT NULL,
    "操作时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果合并审计" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果合并审计_来源类型" CHECK ("来源成果类型" BETWEEN 1 AND 4),
    CONSTRAINT "ck_科研成果合并审计_规范类型" CHECK ("规范成果类型" BETWEEN 1 AND 4),
    CONSTRAINT "ck_科研成果合并审计_非自身" CHECK (NOT ("来源成果类型" = "规范成果类型" AND "来源成果编号" = "规范成果编号"))
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研成果合并审计_来源规范"
    ON "科研成果合并审计" ("来源成果类型", "来源成果编号", "规范成果类型", "规范成果编号");
CREATE INDEX IF NOT EXISTS "ix_科研成果合并审计_规范成果"
    ON "科研成果合并审计" ("规范成果类型", "规范成果编号", "操作时间" DESC);

CREATE OR REPLACE FUNCTION "fn_科研成果治理审计"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO "科研成果治理历史" (
            "成果类型", "成果编号", "原状态", "新状态",
            "原规范成果类型", "原规范成果编号", "新规范成果类型", "新规范成果编号",
            "治理原因", "变更动作", "操作人编号"
        ) VALUES (
            NEW."成果类型", NEW."成果编号", NULL, NEW."状态",
            NULL, NULL, NEW."规范成果类型", NEW."规范成果编号",
            NEW."治理原因", '新增', NEW."操作人编号"
        );
    ELSIF OLD."状态" IS DISTINCT FROM NEW."状态"
       OR OLD."规范成果类型" IS DISTINCT FROM NEW."规范成果类型"
       OR OLD."规范成果编号" IS DISTINCT FROM NEW."规范成果编号"
       OR OLD."治理原因" IS DISTINCT FROM NEW."治理原因"
       OR OLD."操作人编号" IS DISTINCT FROM NEW."操作人编号" THEN
        INSERT INTO "科研成果治理历史" (
            "成果类型", "成果编号", "原状态", "新状态",
            "原规范成果类型", "原规范成果编号", "新规范成果类型", "新规范成果编号",
            "治理原因", "变更动作", "操作人编号"
        ) VALUES (
            NEW."成果类型", NEW."成果编号", OLD."状态", NEW."状态",
            OLD."规范成果类型", OLD."规范成果编号", NEW."规范成果类型", NEW."规范成果编号",
            NEW."治理原因", '更新', NEW."操作人编号"
        );
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS "tr_科研成果治理_审计" ON "科研成果治理";
CREATE TRIGGER "tr_科研成果治理_审计"
AFTER INSERT OR UPDATE ON "科研成果治理"
FOR EACH ROW EXECUTE FUNCTION "fn_科研成果治理审计"();

-- 迁移前已有的治理快照没有操作事件，明确标识为历史导入，便于审计区分。
INSERT INTO "科研成果治理历史" (
    "成果类型", "成果编号", "原状态", "新状态", "新规范成果类型", "新规范成果编号",
    "治理原因", "变更动作", "操作人编号", "操作时间"
)
SELECT g."成果类型", g."成果编号", NULL, g."状态", g."规范成果类型", g."规范成果编号",
       g."治理原因", '历史导入', g."操作人编号", g."操作时间"
  FROM "科研成果治理" g
 WHERE NOT EXISTS (
       SELECT 1 FROM "科研成果治理历史" h
        WHERE h."成果类型" = g."成果类型" AND h."成果编号" = g."成果编号"
          AND h."变更动作" = '历史导入'
   );

UPDATE "系统迁移版本"
   SET "版本" = 83,
       "脚本" = '083_achievement_governance_audit_and_merge.sql',
       "检查摘要" = '增加成果治理不可变历史、重复成果合并审计映射，来源成果保留不删除',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

COMMIT;
